#!/usr/bin/env bash
set -euo pipefail
ROOT="${1:-.}"
cd "$ROOT"
mkdir -p src/aeris/gui
python - <<'PY2'
from pathlib import Path
import base64
app_b64 = """"""
Path("src/aeris/gui").mkdir(parents=True, exist_ok=True)
Path("src/aeris/gui/app.py").write_bytes(base64.b64decode(app_b64))
PY2
python -m py_compile src/aeris/gui/app.py
echo "[AERIS PATCH] GUI v0.5 workflow cockpit written."
echo "  - src/aeris/gui/app.py"
echo "Run: aeris gui run"
